def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Identify background color (most frequent)
    counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    BG = max(counts, key=counts.get) if counts else 0

    output = [row[:] for row in grid]

    # Find connected components
    visited = [[False] * cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if output[r][c] != BG and not visited[r][c]:
                color = output[r][c]
                cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cur_r, cur_c = stack.pop()
                    cells.append((cur_r, cur_c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cur_r + dr, cur_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and output[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                c_min = min(x[1] for x in cells)
                c_max = max(x[1] for x in cells)
                components.append({'color': color, 'cells': cells, 'c_min': c_min, 'c_max': c_max})

    shapes = []
    instructions = []
    instr_ids = []

    for comp in components:
        # Instructions are single pixels in the last row
        is_instruction = False
        if comp['cells']:
            if len(comp['cells']) == 1 and comp['cells'][0][0] == rows - 1:
                is_instruction = True

        if comp['cells']:
            if is_instruction:
                instr_id = comp['color']
                instructions.append({'color': comp['color'], 'c': comp['cells'][0][1], 'id': instr_id})
                instr_ids.append(instr_id)
            else:
                shapes.append(comp)

    # Match instructions to shapes using unique identifiers
    used_instr = {}
    for shape in shapes:
        for inst in instructions:
            # Only match if instruction column falls within shape's horizontal span
            if inst['c'] >= shape['c_min'] and inst['c'] <= shape['c_max']:
                # This is a valid match, apply transformation
                for r, c in shape['cells']:
                    output[r][c] = inst['color']
                # Remove instruction pixel (turn to BG)
                output[rows - 1][inst['c']] = BG
                break

    return output
